INSERT INTO estudante_avaliacao (uuid, id_estudante, id_empresa, id_setor, estado_atuacao, modelo_trabalho, data_inicio, titulo_cargo, texto_avaliacao, salario_min, salario_max, anonima, ambiente, aprendizado, beneficios, cultura, efetivacao, entrevista, feedback, infraestrutura, integracao, remuneracao, rotina, lideranca, created_at) VALUES ('aval-1', 1, 1, 8, 'SP', 'Híbrido', '2023-01-01', 'Estagiário Java', 'Entrei como estagiário e em 6 meses já estava contribuindo em projetos reais com Java e Spring Boot. A GFT tem uma cultura forte de aprendizado, com mentores dedicados. O modelo híbrido funciona bem, com 2 dias no escritório e 3 remotos. Único ponto negativo foi a demora no processo de recrutamento, que levou quase 2 meses.', 2500, 3000, false, 5, 5, 4, 5, 5, 4, 5, 5, 5, 4, 4, 5, NOW());
INSERT INTO estudante_avaliacao (uuid, id_estudante, id_empresa, id_setor, estado_atuacao, modelo_trabalho, data_inicio, titulo_cargo, texto_avaliacao, salario_min, salario_max, anonima, ambiente, aprendizado, beneficios, cultura, efetivacao, entrevista, feedback, infraestrutura, integracao, remuneracao, rotina, lideranca, created_at) VALUES ('aval-2', 2, 8, 8, 'RJ', 'Presencial', '2023-01-10', 'Dev Junior', 'Infelizmente não foi uma boa experiência. Ambiente extremamente pressionado, com metas irreais e pouco suporte dos seniors. A empresa trata desenvolvedores como esteiras de código, sem qualquer preocupação com qualidade de vida. Rotatividade altíssima — em 3 meses vi pelo menos 5 pessoas saírem.', 2000, 2200, false, 1, 2, 1, 1, 1, 2, 1, 2, 1, 2, 1, 1, NOW());
INSERT INTO estudante_avaliacao (uuid, id_estudante, id_empresa, id_setor, estado_atuacao, modelo_trabalho, data_inicio, titulo_cargo, texto_avaliacao, salario_min, salario_max, anonima, ambiente, aprendizado, beneficios, cultura, efetivacao, entrevista, feedback, infraestrutura, integracao, remuneracao, rotina, lideranca, created_at) VALUES ('aval-10', 5, 12, 4, 'SP', 'Híbrido', '2023-01-15', 'Analista Financeiro', 'Salário realmente muito acima do mercado para a posição, e os bônus são generosos. Porém, a cultura é extremamente competitiva e o ritmo é puxado. Se você aguenta pressão e entrega resultados, é um ótimo lugar para crescer financeiramente. Não recomendo para quem busca equilíbrio entre vida pessoal e profissional.', 7000, 9000, false, 3, 5, 5, 2, 4, 4, 3, 5, 3, 5, 1, 2, NOW());
INSERT INTO estudante_avaliacao (uuid, id_estudante, id_empresa, id_setor, estado_atuacao, modelo_trabalho, data_inicio, titulo_cargo, texto_avaliacao, salario_min, salario_max, anonima, ambiente, aprendizado, beneficios, cultura, efetivacao, entrevista, feedback, infraestrutura, integracao, remuneracao, rotina, lideranca, created_at) VALUES ('aval-11', 6, 14, 8, 'SC', 'Remoto', '2023-03-01', 'UX Designer', 'Melhor cultura que já vi em uma empresa de tecnologia. Ambiente remoto bem estruturado, com comunicação assíncrona eficiente e workshops semanais de desenvolvimento pessoal. O salário não é o mais alto do mercado, mas os benefícios não financeiros (horários flexíveis, dias de saúde mental, plano de carreira claro) compensam muito.', 4500, 5000, false, 5, 5, 2, 5, 3, 5, 5, 3, 5, 2, 5, 5, NOW());
INSERT INTO estudante_avaliacao (uuid, id_estudante, id_empresa, id_setor, estado_atuacao, modelo_trabalho, data_inicio, titulo_cargo, texto_avaliacao, salario_min, salario_max, anonima, ambiente, aprendizado, beneficios, cultura, efetivacao, entrevista, feedback, infraestrutura, integracao, remuneracao, rotina, lideranca, created_at) VALUES ('aval-12', 7, 15, 8, 'PR', 'Presencial', '2022-12-01', 'Suporte Técnico', 'Pressão constante e nenhum feedback construtivo dos gestores. O salário é baixo para a região e as condições de trabalho são precárias — cadeiras desconfortáveis, computadores lentos, sem plano de carreira. A única vantagem é que aprendi a me virar sozinho, já que não havia nenhum tipo de treinamento ou onboarding.', 2500, 2800, false, 2, 2, 2, 2, 2, 3, 1, 2, 2, 3, 1, 1, NOW());
INSERT INTO estudante_avaliacao (uuid, id_estudante, id_empresa, id_setor, estado_atuacao, modelo_trabalho, data_inicio, titulo_cargo, texto_avaliacao, salario_min, salario_max, anonima, ambiente, aprendizado, beneficios, cultura, efetivacao, entrevista, feedback, infraestrutura, integracao, remuneracao, rotina, lideranca, created_at) VALUES ('aval-13', 2, 11, 2, 'SP', 'Híbrido', '2023-04-01', 'Estagiária Tech', 'Comecei como estagiária no Magalu e foi uma experiência transformadora. O programa de estágio é bem estruturado, com rotação entre áreas e mentoria de profissionais experientes. Ambiente acolhedor e diverso, com muitas mulheres em posições de liderança. Efetivação com aumento salarial significativo após 1 ano.', 2200, 2500, false, 4, 5, 4, 5, 4, 4, 4, 4, 5, 4, 4, 4, NOW());
INSERT INTO estudante_avaliacao (uuid, id_estudante, id_empresa, id_setor, estado_atuacao, modelo_trabalho, data_inicio, titulo_cargo, texto_avaliacao, salario_min, salario_max, anonima, ambiente, aprendizado, beneficios, cultura, efetivacao, entrevista, feedback, infraestrutura, integracao, remuneracao, rotina, lideranca, created_at) VALUES ('aval-16', 1, 16, 4, 'SP', 'Híbrido', '2023-06-01', 'Dev Java Jr', 'Benefícios simplesmente impecáveis: plano de saúde top, previdência privada com contrapartida, participação nos lucros generosa, auxílio educação, gympass e muito mais. A estrutura do escritório é moderna e o home office funciona bem. Pontos de melhoria: processo burocrático para promoções e excesso de reuniões.', 5000, 6500, false, 4, 5, 5, 4, 5, 4, 4, 5, 4, 5, 3, 4, NOW());
