INSERT INTO estudante_avaliacao (uuid, id_estudante, id_empresa, id_setor, estado_atuacao, modelo_trabalho, data_inicio, titulo_cargo, texto_avaliacao, salario_min, salario_max, anonima, ambiente, aprendizado, beneficios, cultura, efetivacao, entrevista, feedback, infraestrutura, integracao, remuneracao, rotina, lideranca, created_at) VALUES ('aval-20', 5, 1, 8, 'SP', 'Híbrido', '2023-02-01', 'Dev Pleno', 'Vou manter anônimo porque ainda trabalho na área e não quero me expor. No geral é uma boa empresa, com benefícios razoáveis e clima tranquilo. Mas o processo seletivo é extremamente demorado — fiz 5 etapas ao longo de 3 meses. A comunicação entre RH e gestão é confusa, e tive que correr atrás de retorno várias vezes.', 4000, 5500, true, 4, 4, 4, 4, 3, 3, 4, 4, 4, 4, 4, 4, NOW());
INSERT INTO estudante_avaliacao (uuid, id_estudante, id_empresa, id_setor, estado_atuacao, modelo_trabalho, data_inicio, titulo_cargo, texto_avaliacao, salario_min, salario_max, anonima, ambiente, aprendizado, beneficios, cultura, efetivacao, entrevista, feedback, infraestrutura, integracao, remuneracao, rotina, lideranca, created_at) VALUES ('aval-21', 6, 16, 4, 'SP', 'Remoto', '2023-06-01', 'Analista Financeiro', 'Banco sólido com benefícios excelentes, especialmente a previdência privada e o plano de saúde que cobre dependentes sem coparticipação. Por outro lado, o ritmo é intenso e a burocracia interna desgasta. Muitos processos manuais que poderiam ser automatizados. Se você valoriza estabilidade e benefícios, compensa. Se busca inovação e agilidade, talvez não seja o melhor lugar.', 5000, 7000, true, 4, 4, 5, 3, 4, 4, 3, 5, 4, 5, 3, 4, NOW());
INSERT INTO estudante_avaliacao_coment (uuid, id_estudante, id_avaliacao, texto, anonima, created_at) VALUES ('coment-1', 2, 1, 'Fiz estágio lá no ano passado e confirmo cada ponto da avaliação. O time de Java é muito bom, aprendi demais com os seniors. Só adiciono que a GFT investe bastante em certificações — tirei a AWS Cloud Practitioner pagando por eles.', false, NOW());
INSERT INTO estudante_avaliacao_coment (uuid, id_estudante, id_avaliacao, texto, anonima, created_at) VALUES ('coment-2', 5, 1, 'Acho que depende muito do projeto e do gestor. No meu caso, tive uma experiência bem diferente — meu líder era ausente e o projeto estagnado. A avaliação original parece refletir bem um cenário positivo, mas nem todo mundo tem essa sorte.', true, NOW());
INSERT INTO estudante_avaliacao_coment (uuid, id_estudante, id_avaliacao, texto, anonima, created_at) VALUES ('coment-3', 6, 2, 'Tive exatamente a mesma experiência. Fiquei 4 meses e saí. Ambiente tóxico, gestor que nunca dava feedback e ainda cobrava horas extras não remuneradas. Fuja dessa empresa se puder.', false, NOW());
INSERT INTO estudante_avaliacao_coment (uuid, id_estudante, id_avaliacao, texto, anonima, created_at) VALUES ('coment-4', 7, 10, 'Salário realmente é o grande atrativo da XP, mas a avaliação foi justa ao apontar o ritmo intenso. Conheço gente que adora a competição saudável de lá, e gente que pediu as contas em 6 meses porque não aguentou a pressão.', true, NOW());
INSERT INTO estudante_avaliacao_coment (uuid, id_estudante, id_avaliacao, texto, anonima, created_at) VALUES ('coment-5', 1, 13, 'Magalu foi meu primeiro emprego e sou grata até hoje. A cultura de inclusão é genuína — participei de grupos de afinidade e me senti acolhida desde o primeiro dia. O programa de estágio é referência, recomendo de olhos fechados.', false, NOW());
INSERT INTO empresa_avaliacao_coment (uuid, id_empresa, id_avaliacao, texto, created_at) VALUES ('emp-coment-1', 1, 1, 'Agradecemos o feedback detalhado! Ficamos felizes que sua experiência como estagiário foi positiva. Sabemos que nosso processo seletivo pode ser demorado e estamos trabalhando para reduzi-lo. Seus apontamentos sobre os mentores e as certificações nos motivam a continuar investindo em nossos programas de desenvolvimento.', NOW());
INSERT INTO empresa_avaliacao_coment (uuid, id_empresa, id_avaliacao, texto, created_at) VALUES ('emp-coment-2', 8, 2, 'Lamentamos profundamente sua experiência. Estamos passando por uma reestruturação interna para melhorar a qualidade de vida dos nossos colaboradores. Já implementamos um novo programa de onboarding e contratamos novos líderes técnicos. Esperamos que, em uma futura oportunidade, possamos oferecer uma experiência diferente.', NOW());
INSERT INTO empresa_avaliacao_coment (uuid, id_empresa, id_avaliacao, texto, created_at) VALUES ('emp-coment-3', 16, 16, 'Que bom que nossos benefícios fizeram diferença na sua trajetória! Trabalhamos constantemente para oferecer o melhor pacote do mercado. Quanto ao ponto sobre a burocracia para promoções, estamos revisando nosso processo de carreira para torná-lo mais transparente e ágil. Obrigado pela contribuição!', NOW());
